import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../utils/api';
import './QuizPage.css';

const CATEGORY_LABELS = {
  work_style: '🧠 Work Style',
  environment: '🏢 Environment',
  subject: '📖 Academic Background',
  motivation: '🔥 Motivation',
  tools: '🛠 Tools & Methods',
  impact: '🌍 Impact',
  strength: '💪 Strengths',
  learning: '📚 Learning Style',
  tech: '💻 Tech Comfort',
  problem: '🔍 Problem Solving',
  industry: '🏭 Industry',
  team: '👥 Team Preference',
  output: '🏆 Proud Output',
  risk: '⚡ Risk Appetite',
  values: '❤️ Core Values',
  hobby: '🎯 Hobbies',
  salary_vs_purpose: '💼 Salary vs Purpose',
  scale: '🔭 Depth vs Breadth',
  future: '🚀 Future Vision',
  proud_of: '🎖 Greatest Achievement',
};

export default function QuizPage() {
  const navigate = useNavigate();
  const [questions,  setQuestions]  = useState([]);
  const [current,    setCurrent]    = useState(0);
  const [answers,    setAnswers]    = useState({});   // { qid: optionIndex }
  const [selected,   setSelected]   = useState(null); // currently highlighted option
  const [loading,    setLoading]    = useState(true);
  const [submitting, setSubmitting] = useState(false);
  const [error,      setError]      = useState('');
  const [animating,  setAnimating]  = useState(false);

  useEffect(() => {
    api.get('/quiz/questions')
      .then(r => setQuestions(r.data.questions || []))
      .catch(() => setError('Failed to load questions'))
      .finally(() => setLoading(false));
  }, []);

  // Restore previously selected answer when navigating back
  useEffect(() => {
    if (questions[current]) {
      const saved = answers[questions[current].id];
      setSelected(saved !== undefined ? saved : null);
    }
  }, [current, questions, answers]);

  const q = questions[current];
  const progress = questions.length ? ((current) / questions.length) * 100 : 0;
  const answeredCount = Object.keys(answers).length;

  const choose = (optIdx) => {
    setSelected(optIdx);
  };

  const goNext = () => {
    if (selected === null) return;
    const newAnswers = { ...answers, [q.id]: selected };
    setAnswers(newAnswers);

    if (current < questions.length - 1) {
      setAnimating(true);
      setTimeout(() => {
        setCurrent(c => c + 1);
        setAnimating(false);
      }, 280);
    } else {
      // Submit
      handleSubmit(newAnswers);
    }
  };

  const goPrev = () => {
    if (current > 0) {
      setAnimating(true);
      setTimeout(() => {
        setCurrent(c => c - 1);
        setAnimating(false);
      }, 200);
    }
  };

  const handleSubmit = async (finalAnswers) => {
    setSubmitting(true);
    setError('');
    try {
      const payload = Object.entries(finalAnswers).map(([qid, optIdx]) => ({
        question_id: parseInt(qid),
        option_index: optIdx,
      }));
      const res = await api.post('/quiz/submit', { answers: payload });
      // Pass results via navigation state
      navigate('/quiz/results', { state: res.data });
    } catch (e) {
      setError(e.message);
      setSubmitting(false);
    }
  };

  if (loading) return (
    <div className="quiz-loading">
      <div className="spinner" style={{ width: 48, height: 48 }} />
      <p>Loading your career quiz…</p>
    </div>
  );

  if (submitting) return (
    <div className="quiz-loading">
      <div className="quiz-analyzing">
        <div className="analyzing-ring" />
        <div className="analyzing-inner">🤖</div>
      </div>
      <h2 style={{ marginTop: 24 }}>Analysing your answers…</h2>
      <p style={{ color: 'var(--text-2)', marginTop: 8 }}>
        Building your personalised career roadmap
      </p>
    </div>
  );

  return (
    <div className="quiz-layout">
      {/* Header */}
      <div className="quiz-header">
        <div className="container">
          <div className="quiz-header-inner">
            <div>
              <h2 className="quiz-title">Career Discovery Quiz</h2>
              <p className="quiz-subtitle">
                {answeredCount} of {questions.length} questions answered
              </p>
            </div>
            <div className="quiz-counter">
              <span className="counter-current">{current + 1}</span>
              <span className="counter-sep">/</span>
              <span className="counter-total">{questions.length}</span>
            </div>
          </div>
          {/* Progress bar */}
          <div className="quiz-progress">
            <div className="quiz-progress-fill" style={{ width: `${progress}%` }} />
          </div>
        </div>
      </div>

      {/* Question card */}
      <div className="quiz-body container">
        {error && (
          <div className="alert alert-error" style={{ marginBottom: 20 }}>{error}</div>
        )}

        {q && (
          <div className={`quiz-card ${animating ? 'slide-out' : 'slide-in'}`}>
            {/* Category label */}
            <div className="q-category">
              {CATEGORY_LABELS[q.category] || q.category}
            </div>

            {/* Question */}
            <h2 className="q-text">{q.question}</h2>

            {/* Options */}
            <div className="q-options">
              {q.options.map((opt, i) => (
                <button
                  key={i}
                  className={`q-option ${selected === i ? 'selected' : ''}`}
                  onClick={() => choose(i)}
                >
                  <div className="option-letter">{String.fromCharCode(65 + i)}</div>
                  <span className="option-text">{opt.label}</span>
                  {selected === i && (
                    <div className="option-check">✓</div>
                  )}
                </button>
              ))}
            </div>

            {/* Navigation */}
            <div className="q-nav">
              <button
                className="btn btn-ghost"
                onClick={goPrev}
                disabled={current === 0}
              >
                ← Back
              </button>

              <div className="dot-indicators">
                {questions.map((_, i) => (
                  <div
                    key={i}
                    className={`dot ${i === current ? 'active' : ''} ${answers[questions[i]?.id] !== undefined ? 'answered' : ''}`}
                    onClick={() => {
                      if (answers[questions[i]?.id] !== undefined || i <= current) {
                        setAnimating(true);
                        setTimeout(() => { setCurrent(i); setAnimating(false); }, 200);
                      }
                    }}
                  />
                ))}
              </div>

              <button
                className={`btn ${selected !== null ? 'btn-primary' : 'btn-ghost'}`}
                onClick={goNext}
                disabled={selected === null}
              >
                {current === questions.length - 1 ? '🚀 See Results' : 'Next →'}
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
